     "summary": "美国参议员桑德斯表示，去年，亚马逊(AMZN.O)创始人贝佐斯乘坐价值5亿美元的游艇前往威尼斯，举行了一场耗资5500万美元的婚礼，并送给妻子一枚价值500万美元的戒指，而当时他的实际税率还不到1%。按照我设定的5%亿万富翁财富税，贝佐斯先生将欠下127亿美元，但其身家仍能剩下2400亿美元。 （文章来源：金十数据快讯）",
